const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const app=$('#app');let db,state,view='library',filter='all',query='',sort='recent',layout='grid',pageQuery='',selected=null,pageId=null,tool='pen',inkColor='#eee8db',width=3,zoom=1,focus=false,engine=null,updateAvailable=false,saveTimer,saveChain=Promise.resolve(),revision=0,savedRevision=0,saveFailed=false,storageVersion=0;
const history=new Map(),redo=new Map();let toastTimer,saveIdle=0,thumbTimer=0,thumbIdle=0;const thumbQueue=new Set();
const currentBook=()=>state.notebooks.find(n=>n.id===selected),currentPage=()=>currentBook()?.pages.find(p=>p.id===pageId);
const button=(action,label,ico,cls='',extra='')=>`<button class="${cls}" data-action="${action}" title="${esc(label)}" aria-label="${esc(label)}" ${extra}>${ico?icon(ico):''}<span>${esc(label)}</span></button>`;
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
function saveStatus(){for(const e of document.querySelectorAll('.save-label'))e.innerHTML=icon(saveFailed?'help':savedRevision===revision?'check':'more',14)+`<span>${saveFailed?'Not saved · export a backup':savedRevision===revision?'Saved on this device':'Saving…'}</span>`;}
function saveNow(){clearTimeout(saveTimer);saveTimer=0;if(saveIdle&&typeof cancelIdleCallback==='function')cancelIdleCallback(saveIdle);saveIdle=0;const r=revision,snapshot=structuredClone(state);saveChain=saveChain.catch(()=>{}).then(async()=>{snapshot.storageRevision=storageVersion+1;await writeState(db,snapshot,storageVersion);storageVersion=snapshot.storageRevision;state.storageRevision=storageVersion;}).then(()=>{savedRevision=r;saveFailed=false;saveStatus();}).catch(err=>{saveFailed=true;saveStatus();toast(err.message?.startsWith('Another tab')?err.message:'Could not save. Export a backup before closing this page.');});return saveChain;}
function scheduleSave(){clearTimeout(saveTimer);if(saveIdle&&typeof cancelIdleCallback==='function')cancelIdleCallback(saveIdle);saveIdle=0;saveTimer=setTimeout(flushSave,800);}
function flushSave(){saveTimer=0;if(engine?.activePenId!==null){saveTimer=setTimeout(flushSave,400);return;}const run=()=>{saveIdle=0;if(engine?.activePenId!==null){saveTimer=setTimeout(flushSave,400);return;}saveNow();};if(typeof requestIdleCallback==='function')saveIdle=requestIdleCallback(run,{timeout:500});else run();}
function changed(){state.updatedAt=Date.now();revision++;saveStatus();scheduleSave();}
function touchPage(){const p=currentPage(),n=currentBook();p.updatedAt=n.updatedAt=Date.now();changed();}
function pushOp(p,op){if(!history.has(p.id))history.set(p.id,[]);const h=history.get(p.id);h.push(op);if(h.length>30)h.shift();redo.set(p.id,[]);}
function replay(p,op,forward){if(op.type==='add'){if(forward)p.strokes.push(op.stroke);else{const i=p.strokes.lastIndexOf(op.stroke);if(i>=0)p.strokes.splice(i,1);}}else if(forward){const drop=new Set(op.removed.map(r=>r.stroke));p.strokes=p.strokes.filter(s=>!drop.has(s));}else for(const r of [...op.removed].sort((a,b)=>a.index-b.index))p.strokes.splice(Math.min(r.index,p.strokes.length),0,r.stroke);}
function updateUndo(){const p=currentPage();if(!p)return;const a=$('[data-action="undo"]'),b=$('[data-action="redo"]');if(a)a.disabled=!history.get(p.id)?.length;if(b)b.disabled=!redo.get(p.id)?.length;}
function undoInk(reverse=false){const p=currentPage(),from=reverse?redo:history,to=reverse?history:redo;const stack=from.get(p.id);if(!stack?.length)return;const op=stack.pop();if(!to.has(p.id))to.set(p.id,[]);to.get(p.id).push(op);replay(p,op,reverse);redrawStatic();touchPage();updateUndo();updateThumb();}
function scheduleThumb(p=currentPage()){if(!p)return;thumbQueue.add(p);clearTimeout(thumbTimer);if(thumbIdle&&typeof cancelIdleCallback==='function')cancelIdleCallback(thumbIdle);thumbIdle=0;thumbTimer=setTimeout(flushThumbs,800);}
function flushThumbs(){thumbTimer=0;if(engine?.activePenId!==null){thumbTimer=setTimeout(flushThumbs,400);return;}const run=()=>{thumbIdle=0;if(engine?.activePenId!==null){thumbTimer=setTimeout(flushThumbs,400);return;}const pages=[...thumbQueue];thumbQueue.clear();for(const q of pages)updateThumb(q);};if(typeof requestIdleCallback==='function')thumbIdle=requestIdleCallback(run,{timeout:500});else run();}
function sidebar(){const count=state.notebooks.length;return `<aside class="sidebar"><a href="#" class="wordmark" data-action="home">zero<span> ·</span></a><div class="workspace-label">YOUR PERSONAL SPACE</div><button class="search-launch" data-action="search">${icon('search',17)}<span>Find a thought</span><kbd>⌘ K</kbd></button><nav aria-label="Notebook navigation">${nav('all','All notebooks','book',count)}${nav('favorites','Favorites','star',state.notebooks.filter(n=>n.favorite).length)}<div class="section-label">COLLECTIONS ${button('new-collection','New collection','plus','icon-button small')}</div>${state.collections.map(c=>nav(c.id,c.title,'folder',state.notebooks.filter(n=>n.collection===c.id).length)).join('')}${!state.collections.length?'<p class="collection-hint">A little order for your ideas.</p>':''}${button('new-collection','Create a collection','plus','subtle add-collection')}</nav><div class="sidebar-bottom"><div class="local-note"><span class="tiny-dot"></span> YOURS, ALWAYS.<p>Saved here. Ready when you are.</p></div>${button('recently-deleted','Recently deleted','trash','sidebar-action')}${button('backup','Export workspace','download','sidebar-action')}${button('import','Import backup','upload','sidebar-action')}${button('help','A little guidance','help','sidebar-action')}<div class="app-version"><div><span>Version ${esc(APP_VERSION)}</span><small>Build ${esc(buildLabel())}</small></div><button type="button" data-action="update-app" class="${updateAvailable?'has-update':''}">Update</button></div><div class="profile"><div class="avatar">0</div><div>Personal workspace<small>A space to make your own</small></div></div></div></aside>`;}
function nav(v,label,ico,count){return `<button class="nav-item ${filter===v?'active':''}" data-action="filter" data-value="${esc(v)}">${icon(ico,18)}<span>${esc(label)}</span><small>${count}</small></button>`;}
function header(){return `<header class="topbar"><div class="breadcrumbs">${button('mobile-menu','Navigation','menu','icon-button mobile-only')}<span>Your workspace</span>${icon('chevron',13)}<strong>${esc(filter==='favorites'?'Favorites':state.collections.find(c=>c.id===filter)?.title||'All notebooks')}</strong></div><div class="save-label"></div></header>`;}
function library(){return `<div class="shell">${sidebar()}<main class="main">${header()}<section class="library"><div class="hero"><div class="eyebrow"><span></span> A LITTLE SPACE. ENDLESS POSSIBILITY.</div><h1>Make room<br>for your <em>mind.</em></h1><p>For passing thoughts. For beautiful beginnings.<br>For everything still taking shape.</p><div class="hero-buttons">${button('new-notebook','New notebook','plus','primary')}${resumeButton()}</div><div class="hero-art" aria-hidden="true"><div class="art-sheet sheet-back"></div><div class="art-sheet sheet-front"><div class="art-rule"></div><span>Thoughts<br><em>in motion.</em></span><svg viewBox="0 0 220 140"><path d="M10 100C50 12 70 145 110 50S160 150 205 36"/><path d="M10 115C50 27 70 160 110 65S160 165 205 51"/></svg><small>AN OPEN PAGE IS A POSSIBILITY</small></div><div class="art-pencil"></div></div></div><div class="shelf-heading"><div><span class="eyebrow">THE COLLECTION</span><h2>${esc(filter==='favorites'?'Close to heart':state.collections.find(c=>c.id===filter)?.title||'Your notebooks')}<span id="result-count"></span></h2></div><div class="shelf-controls"><label class="search-field">${icon('search',17)}<input type="search" id="search" placeholder="Search your notes…" value="${esc(query)}" aria-label="Search notebooks and pages"></label><select id="sort" aria-label="Sort notebooks"><option value="recent" ${sort==='recent'?'selected':''}>Last edited</option><option value="name" ${sort==='name'?'selected':''}>By name</option><option value="created" ${sort==='created'?'selected':''}>Newest first</option></select><button class="icon-button" data-action="layout" aria-label="Switch notebook layout">${icon(layout==='grid'?'list':'grid',18)}</button>${state.collections.some(c=>c.id===filter)?button('collection-menu','Collection settings','more','icon-button'):''}</div></div><div id="notebooks" class="notebook-grid ${layout==='list'?'list-layout':''}"></div><footer class="library-footer"><span>YOUR NEXT GREAT IDEA STARTS WITH A SINGLE NOTE.</span><span>Made for a quieter kind of focus ${icon('leaf',14)}</span></footer></section></main></div>`;}
function filteredBooks(){return state.notebooks.filter(n=>(filter==='all'||filter==='favorites'&&n.favorite||n.collection===filter)&&(!query||[n.title,...n.pages.flatMap(p=>[p.title,p.text])].some(t=>t.toLowerCase().includes(query.toLowerCase())))).sort((a,b)=>sort==='name'?a.title.localeCompare(b.title):sort==='created'?b.createdAt-a.createdAt:b.updatedAt-a.updatedAt);}
function date(t){return new Date(t).toLocaleDateString(undefined,{month:'short',day:'numeric'});}
function renderBooks(){const books=filteredBooks();$('#result-count').textContent=`${books.length.toString().padStart(2,'0')}`;$('#notebooks').innerHTML=books.map((n,i)=>`<article class="notebook-card" style="--accent:${n.color};--delay:${i*45}ms"><button class="cover cover-${i%3}" data-action="open" data-id="${n.id}" aria-label="Open ${esc(n.title)}"><div class="book-spine"></div><div class="cover-top"><span>ZERO / VOL. ${String(state.notebooks.indexOf(n)+1).padStart(2,'0')}</span>${icon('book',16)}</div><div class="cover-drawing"><i></i><i></i><i></i><i></i></div><div class="cover-title">${esc(n.title)}</div><div class="cover-bottom"><span>${esc(state.collections.find(c=>c.id===n.collection)?.title||'PERSONAL NOTES')}</span><span>${String(n.pages.length).padStart(2,'0')} PAGES</span></div></button><div class="book-meta"><button data-action="open" data-id="${n.id}" class="book-title">${esc(n.title)}</button><button class="icon-button small ${n.favorite?'is-favorite':''}" data-action="favorite" data-id="${n.id}" aria-label="${n.favorite?'Unfavorite':'Favorite'} ${esc(n.title)}" aria-pressed="${!!n.favorite}">${icon('star',16)}</button><button class="icon-button small" data-action="book-menu" data-id="${n.id}" aria-label="Options for ${esc(n.title)}">${icon('more',18)}</button><small>${n.pages.length} ${n.pages.length===1?'page':'pages'} <span>·</span> Edited ${date(n.updatedAt)}</small></div></article>`).join('')+(query?'':`<button class="new-book-card" data-action="new-notebook"><span class="plus-ring">${icon('plus',26)}</span><strong>A fresh beginning</strong><small>Create a notebook</small></button>`);if(!books.length&&query)$('#notebooks').innerHTML='<div class="empty"><h3>No thoughts found. Yet.</h3><p>Try a different word from a notebook or page.</p></div>';}
function editor(){const n=currentBook(),p=currentPage();return `<div class="editor ${focus?'focus-mode':''}"><header class="editor-header"><div class="editor-identity">${button('home','Your notebooks','arrow','icon-button')}<div class="divider"></div><span class="mini-book" style="color:${n.color}">${icon('book',22)}</span><div><button class="editor-book-title" data-action="book-menu" data-id="${n.id}">${esc(n.title)} ${icon('chevron',12)}</button><div class="save-label"></div></div></div><div class="editor-actions">${button('page-panel','Show pages','list','icon-button')} ${button('focus','Focus mode','expand','icon-button',`aria-pressed="${focus}"`)}${button('pen-settings','Ink settings','pen','icon-button')}${button('update-app','Update','refresh','secondary compact'+(updateAvailable?' has-update':''))}${button('backup','Export workspace backup','book','icon-button')}${button('export-page','Export page','download','secondary compact')}</div></header><div class="editor-body"><aside class="page-panel"><div class="pages-heading"><span>PAGES <small>${n.pages.length}</small></span>${button('add-page','Add page','plus','icon-button small')}</div><label class="page-search">${icon('search',14)}<input id="page-search" type="search" value="${esc(pageQuery)}" placeholder="Find a page…" aria-label="Search pages in notebook"></label><div class="page-list">${n.pages.map((q,i)=>`<button class="page-item ${q.id===p.id?'selected':''}" data-action="select-page" data-id="${q.id}" ${matchingPages(n,pageQuery).includes(q)?'':'hidden'}><div class="page-preview template-${q.template}"><canvas width="150" height="200" data-thumb="${q.id}"></canvas>${!q.strokes.length&&!q.text?'<span class="blank-page">An open possibility</span>':''}</div><div class="page-caption"><span>${String(i+1).padStart(2,'0')}</span><strong>${esc(q.title)}</strong></div></button>`).join('')}</div>${button('add-page','Another page','plus','add-page')}<div class="page-panel-footer">Room for every thought.</div></aside><main class="editor-workspace"><div class="page-heading"><input id="page-title" maxlength="160" value="${esc(p.title)}" aria-label="Page title"><button class="icon-button" data-action="page-menu" aria-label="Page options">${icon('more',20)}</button></div><div class="drawing-tools" role="toolbar" aria-label="Drawing tools"><div class="tool-group">${['pen','highlighter','eraser','text'].map(t=>`<button class="tool-button ${tool===t?'selected':''}" data-action="tool" data-value="${t}" aria-label="${{pen:'Pen',highlighter:'Highlighter',eraser:'Stroke eraser',text:'Text'}[t]}" aria-pressed="${tool===t}" title="${t==='eraser'?'Stroke eraser':t}">${icon(t,21)}</button>`).join('')}</div><span class="tool-separator"></span><div class="swatches">${['#eee8db','#c4aa79','#9eafa4','#a4b7c9','#c49d9c'].map(c=>`<button class="swatch ${inkColor===c?'selected':''}" style="--swatch:${c}" data-action="color" data-value="${c}" aria-label="${{'#eee8db':'Ivory','#c4aa79':'Champagne','#9eafa4':'Sage','#a4b7c9':'Blue','#c49d9c':'Rose'}[c]} ink" aria-pressed="${inkColor===c}"></button>`).join('')}</div><span class="tool-separator"></span><label class="width-control" title="Stroke width"><span class="stroke-sample"></span><input id="width" type="range" min="1" max="10" step=".5" value="${width}" aria-label="Stroke width"></label><span class="tool-separator"></span>${button('undo','Undo ink','undo','icon-button')}${button('redo','Redo ink','redo','icon-button')}</div><div class="paper-scroll"><div class="paper template-${p.template}${tool!=='text'?' ink-mode':''}" style="width:${900*zoom}px;height:${1200*zoom}px;background-size:${28*zoom}px ${28*zoom}px;background-position:${18*zoom}px ${18*zoom}px"><textarea class="page-text" id="page-text" maxlength="200000" aria-label="Page text" placeholder="Let a thought take shape…" spellcheck="true" style="font-size:${24*zoom}px;line-height:${38*zoom}px;padding:${78*zoom}px;" ${tool!=='text'?'readonly tabindex="-1"':''}>${esc(p.text)}</textarea><canvas id="ink-static" width="900" height="1200" aria-hidden="true"></canvas><canvas id="ink" width="900" height="1200" aria-label="Drawing canvas. Use Apple Pencil or a mouse." class="${tool==='text'?'text-mode':''}"></canvas></div></div><footer class="canvas-footer"><div><span class="tiny-dot"></span><label class="pencil-switch"><input id="pencil-only" type="checkbox" ${state.settings.pencilOnly?'checked':''}> Pencil only</label><span class="footer-tip">${tool==='eraser'?'Erase entire strokes':tool==='text'?'A little space for your words':'Two fingers to move · Pencil to write'}</span></div><div><select id="template" aria-label="Page background">${['dots','grid','ruled','blank'].map(t=>`<option ${p.template===t?'selected':''} value="${t}">${t.charAt(0).toUpperCase()+t.slice(1)}</option>`).join('')}</select><button class="zoom-button" data-action="zoom-out" aria-label="Zoom out">−</button><span class="zoom-label">${Math.round(zoom*100)}%</span><button class="zoom-button" data-action="zoom-in" aria-label="Zoom in">+</button><button class="zoom-fit" data-action="zoom-fit">Fit</button></div></footer></main></div></div>`;}
function render(){engine=null;app.innerHTML=view==='library'?library():editor();if(view==='library')renderBooks();else setupCanvas();saveStatus();}
// --- ApplePencilInkEngine wiring -------------------------------------------
// The engine works in canvas CSS pixels (900*zoom x 1200*zoom on screen);
// Zero stores strokes in the fixed 900x1200 document space. The engine's
// contexts are scaled by devicePixelRatio only, so a CSS-pixel point maps
// to the right backing pixel, and the adapter converts CSS <-> document
// space by dividing / multiplying by zoom. The ruled paper is a CSS
// background on .paper, never drawn on either canvas, so the engine's
// destination-out eraser can only erase ink, never the page lines.
function inkRatio(){return Math.min(window.devicePixelRatio||1,2);}
function sizeInkCanvas(canvas){const ratio=inkRatio();canvas.width=Math.round(900*zoom*ratio);canvas.height=Math.round(1200*zoom*ratio);canvas.getContext('2d').setTransform(ratio,0,0,ratio,0,0);}
function syncEngine(){if(!engine)return;if(tool==='pen'||tool==='highlighter'||tool==='eraser')engine.tool=tool;engine.color=inkColor;engine.baseWidth=width*zoom;}
function redrawStatic(){
  if(!engine)return;
  const p=currentPage();if(!p)return;
  const ctx=engine.staticCtx;
  ctx.setTransform(inkRatio(),0,0,inkRatio(),0,0);
  ctx.clearRect(0,0,engine.staticCanvas.width,engine.staticCanvas.height);
  for(const s of p.strokes)engine.drawStrokeToContext(ctx,zeroStrokeToEngine(s,zoom));
  engine.clearActiveCanvas();
}
function handleStrokeComplete(stroke){
  const p=currentPage();if(!p)return;
  if(stroke.tool==='eraser'){
    // Zero's eraser removes whole strokes, and eraser strokes are never
    // stored. Hit-test the eraser path (in document space) against the
    // saved strokes, drop the ones it crossed, and re-render so the
    // pixel-erase the engine did live is replaced by the true result.
    const removed=[];
    p.strokes.forEach((s,index)=>{if(stroke.points.some(pt=>{const [x,y]=toDocPoint(pt,zoom);return hitStroke(s,x,y);}))removed.push({index,stroke:s});});
    if(!removed.length){redrawStatic();return;}
    const drop=new Set(removed.map(r=>r.stroke));
    p.strokes=p.strokes.filter(s=>!drop.has(s));
    pushOp(p,{type:'erase',removed});
    touchPage();scheduleThumb(p);updateUndo();redrawStatic();
    return;
  }
  const s=engineStrokeToZero(stroke,zoom);
  if(!s){redrawStatic();return;}
  p.strokes.push(s);pushOp(p,{type:'add',stroke:s});
  touchPage();scheduleThumb(p);updateUndo();redrawStatic();
}
function handlePanZoom({dx,dy,scaleRatio}){
  const host=$('.paper-scroll');if(!host)return;
  host.scrollLeft-=dx;host.scrollTop-=dy;
  if(scaleRatio&&Math.abs(scaleRatio-1)>0.001)applyZoom(zoom*scaleRatio);
}
function setupCanvas(){
  const staticCanvas=$('#ink-static'),activeCanvas=$('#ink');
  sizeInkCanvas(staticCanvas);sizeInkCanvas(activeCanvas);
  engine=new ApplePencilInkEngine({
    staticCanvas,
    activeCanvas,
    onStrokeComplete:handleStrokeComplete,
    onTwoFingerPanZoom:handlePanZoom,
    allowMouse:true,
    allowTouchDraw:!state.settings.pencilOnly,
  });
  syncEngine();
  redrawStatic();
  updateUndo();
  for(const q of currentBook().pages)updateThumb(q);
}function updateThumb(p=currentPage()){const c=document.querySelector(`[data-thumb="${p.id}"]`);if(c){if(p.text||p.strokes.length)c.parentElement.querySelector('.blank-page')?.remove();const x=c.getContext('2d');x.clearRect(0,0,150,200);x.drawImage(pageImage(p),0,0,150,200);}}
function openBook(n){selected=n.id;pageQuery='';pageId=resumePage(n).id;state.lastOpened=n.id;view='editor';focus=false;zoom=Math.min(1,Math.max(.3,(innerWidth-(innerWidth>760?260:40))/940));changed();render();}
function modal(title,body,submitLabel,onSubmit){const d=$('#dialog');d.innerHTML=`<form method="dialog"><div class="modal-top"><span class="eyebrow">ZERO / YOUR WORKSPACE</span><button type="button" class="icon-button" data-close aria-label="Close dialog">${icon('close',20)}</button></div><h2>${esc(title)}</h2>${body}<div class="modal-actions"><button type="button" class="secondary" data-close>Cancel</button><button class="primary" type="submit">${esc(submitLabel)}</button></div></form>`;d.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>d.close());d.querySelector('form').onsubmit=e=>{e.preventDefault();if(!e.target.reportValidity())return;onSubmit(new FormData(e.target));d.close();};d.showModal();setTimeout(()=>d.querySelector('input,select,button[type="submit"]')?.focus(),30);}
function newBook(){modal('A fresh beginning.',`<p class="modal-description">Give your next collection of thoughts a name.</p><label>Notebook name<input name="title" required maxlength="120" placeholder="Something worth keeping" autocomplete="off"></label><label>Collection<select name="collection"><option value="">Personal notes</option>${state.collections.map(c=>`<option value="${c.id}" ${filter===c.id?'selected':''}>${esc(c.title)}</option>`).join('')}</select></label><label>Cover accent</label><div class="accent-options">${colors.map((c,i)=>`<label style="--accent:${c}"><input type="radio" name="color" value="${c}" ${i===0?'checked':''}><span></span></label>`).join('')}</div>`,'Create notebook',f=>{const n=notebook(f.get('title').trim()||'Untitled notebook',f.get('collection')||null,f.get('color'));state.notebooks.push(n);changed();openBook(n);toast('A new beginning. Make it yours.');});}
function newCollection(){modal('A place for related ideas.',`<label>Collection name<input name="title" maxlength="120" required placeholder="Projects, journals, possibilities…"></label>`,'Create collection',f=>{const c={id:id(),title:f.get('title').trim()||'New collection'};state.collections.push(c);filter=c.id;view='library';changed();render();});}
function bookMenu(n){modal('Notebook details.',`<label>Name<input name="title" value="${esc(n.title)}" maxlength="120" required></label><label>Collection<select name="collection"><option value="">Personal notes</option>${state.collections.map(c=>`<option value="${c.id}" ${n.collection===c.id?'selected':''}>${esc(c.title)}</option>`).join('')}</select></label><label>Cover accent<select name="color">${colors.map((c,i)=>`<option value="${c}" ${n.color===c?'selected':''}>${['Champagne','Silver','Sage','Rose','Lavender'][i]}</option>`).join('')}</select></label><div class="detail-actions">${button('duplicate-book','Duplicate','copy','secondary','data-id="'+n.id+'"')}${button('delete-book','Delete notebook','trash','danger','data-id="'+n.id+'"')}</div>`,'Save changes',f=>{n.title=f.get('title').trim()||'Untitled notebook';n.collection=f.get('collection')||null;n.color=f.get('color')||n.color;n.updatedAt=Date.now();changed();render();});$('#dialog .detail-actions').querySelectorAll('button').forEach(b=>b.type='button');}
function pageMenu(){const n=currentBook(),p=currentPage();modal('A little page keeping.',`<p class="modal-description">${esc(p.title)}</p><div class="detail-actions">${button('duplicate-page','Duplicate page','copy','secondary')}${button('move-page-up','Move earlier','arrow','secondary',''+(n.pages.indexOf(p)===0?'disabled':''))}${button('move-page-down','Move later','chevron','secondary',''+(n.pages.indexOf(p)===n.pages.length-1?'disabled':''))}${button('delete-page','Delete page','trash','danger')}</div>`,'Done',()=>{});$('#dialog .detail-actions').querySelectorAll('button').forEach(b=>b.type='button');}
function confirmDelete(title,message,action){$('#dialog').close();modal(title,`<p class="modal-description">${esc(message)}</p>`,'Delete',()=>{action();changed();render();});}
function exportBackup(){download(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),`zero-backup-${new Date().toISOString().slice(0,10)}.json`);toast('Your workspace, ready to take with you.');}
function exportPage(){const p=currentPage();modal('Take this page with you.',`<p class="modal-description">Export a high-resolution image, or print this notebook to save a PDF.</p><label>Format<select name="format"><option value="png">Current page · PNG image</option><option value="pdf">All notebook pages · Print / PDF</option></select></label>`,'Export',f=>{if(f.get('format')==='png')pageImage(p).toBlob(b=>{if(b)download(b,(p.title.replace(/[^a-z0-9-_ ]/gi,'').slice(0,80)||'Zero page')+'.png');else toast('Image export failed. Try again.');});else{const old=$('#print-area');old?.remove();const a=document.createElement('section');a.id='print-area';for(const q of currentBook().pages){const img=new Image();img.src=pageImage(q).toDataURL();img.alt=q.title;a.append(img);}document.body.append(a);setTimeout(()=>window.print(),200);}});}
function resumeButton(){const n=state.notebooks.find(n=>n.id===state.lastOpened);return n?`<button class="resume-button" data-action="resume">${icon('chevron',15)}<span>Pick up where you left off<small>${esc(n.title)} · ${esc(resumePage(n).title)}</small></span></button>`:'';}
function penSettings(){modal('Make your mark.',`<p class="modal-description">Choose the weight and color of your ink. Your preferences stay with this workspace.</p><label>Stroke width<input name="width" type="range" min="1" max="10" step=".5" value="${width}" aria-label="Preferred stroke width"></label><label>Ink color<input name="color" type="color" value="${inkColor}" aria-label="Custom ink color"></label>`,'Set ink',f=>{width=Number(f.get('width'));inkColor=f.get('color');state.settings.penWidth=width;state.settings.penColor=inkColor;changed();render();});}
function showTrash(){const entries=state.trash||[];modal('Nothing lost.',`<p class="modal-description">Deleted pages and notebooks stay here until you restore them. They are included in workspace backups.</p><div class="trash-list">${entries.length?entries.map(e=>`<div class="trash-row"><span>${icon(e.kind==='notebook'?'book':'text',18)}</span><div><strong>${esc(e.data.title)}</strong><small>${e.kind==='page'?'Page · '+esc(e.bookTitle):'Notebook'} · ${date(e.deletedAt)}</small></div><button type="button" class="secondary" data-action="restore-item" data-id="${e.id}">Restore</button></div>`).join(''):'<p class="trash-empty">A clean slate. Nothing to restore.</p>'}</div>`,'Done',()=>{});}
function help(){modal('Welcome to Zero.',`<div class="help-copy"><p><strong>A notebook, a little more room.</strong><br>Create notebooks, add pages, and group them into collections. Recently deleted keeps removed notebooks and pages recoverable. Each notebook remembers your last page. Search finds notebook names, page titles, and typed text.</p><p><strong>Made for your Pencil.</strong><br>Write with Apple Pencil in Safari on a compatible iPad. Pressure changes pen width when the browser supplies it. Two fingers pan and pinch-zoom the page; a single finger is ignored in Pencil only mode, so your palm won't make marks. A mouse still draws. Choose Text to type or use iPad Scribble in the text field.</p><p><strong>Kept on this device.</strong><br>Your notes autosave in this browser. Export backups regularly: clearing website data removes local notes. Import merges a backup into your workspace. There is no cloud sync yet. Update, in the sidebar or at the top of a notebook, installs the newest version after your notes are saved.</p><p><strong>A few small details.</strong><br>⌘/Ctrl K searches. ⌘/Ctrl Z undoes ink while the canvas is active. The eraser removes whole strokes. Pencil Pro squeeze, double-tap, barrel roll, and haptics are not implemented in this web edition.</p></div>`,'Make something',()=>{});}
function setTool(t){tool=t;document.querySelectorAll('[data-action="tool"]').forEach(b=>{b.classList.toggle('selected',b.dataset.value===t);b.setAttribute('aria-pressed',b.dataset.value===t);});const ink=$('#ink'),text=$('#page-text'),paper=$('.paper');ink?.classList.toggle('text-mode',t==='text');paper?.classList.toggle('ink-mode',t!=='text');if(text){text.readOnly=t!=='text';text.tabIndex=t==='text'?0:-1;if(t==='text')text.focus({preventScroll:true});else{try{const i=text.selectionStart||0;text.setSelectionRange(i,i);}catch{}text.blur();const sel=document.getSelection?.();if(sel?.anchorNode&&paper?.contains(sel.anchorNode))sel.removeAllRanges();}}const tip=$('.footer-tip');if(tip)tip.textContent=t==='eraser'?'Erase entire strokes':t==='text'?'A little space for your words':'Two fingers to move · Pencil to write';syncEngine();}
function applyZoom(z){const host=$('.paper-scroll'),old=zoom;zoom=Math.max(.25,Math.min(1.75,z));if(zoom===old)return;const paper=$('.paper'),text=$('#page-text');paper.style.width=900*zoom+'px';paper.style.height=1200*zoom+'px';paper.style.backgroundSize=`${28*zoom}px ${28*zoom}px`;paper.style.backgroundPosition=`${18*zoom}px ${18*zoom}px`;text.style.fontSize=24*zoom+'px';text.style.lineHeight=38*zoom+'px';text.style.padding=78*zoom+'px';host.scrollTop*=zoom/old;$('.zoom-label').textContent=Math.round(zoom*100)+'%';if(engine){sizeInkCanvas($('#ink-static'));sizeInkCanvas($('#ink'));syncEngine();redrawStatic();}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,n=state.notebooks.find(n=>n.id===b.dataset.id);e.preventDefault();if(a==='home'){view='library';render();}else if(a==='filter'){filter=b.dataset.value;query='';view='library';render();}else if(a==='open')openBook(n);else if(a==='new-notebook')newBook();else if(a==='new-collection')newCollection();else if(a==='favorite'){n.favorite=!n.favorite;changed();render();}else if(a==='book-menu')bookMenu(n);else if(a==='layout'){layout=layout==='grid'?'list':'grid';render();}else if(a==='search'){if(view!=='library'){view='library';render();}$('#search').focus();}else if(a==='mobile-menu')$('.sidebar').classList.toggle('mobile-open');else if(a==='backup')exportBackup();else if(a==='import')$('#import-file').click();else if(a==='help')help();else if(a==='update-app')runUpdate();else if(a==='recently-deleted')showTrash();else if(a==='restore-item'){restoreItem(state,b.dataset.id);changed();render();$('#dialog').close();showTrash();toast('Restored to your notebooks.');}else if(a==='pen-settings')penSettings();else if(a==='resume'){const book=state.notebooks.find(n=>n.id===state.lastOpened);if(book)openBook(book);}else if(a==='duplicate-book'){$('#dialog').close();state.notebooks.push(duplicateNotebook(n));changed();render();toast('Notebook duplicated.');}else if(a==='delete-book')confirmDelete('Move notebook to Recently deleted?','You can restore this notebook and all its pages whenever you need them.',()=>{trashNotebook(state,n.id);view='library';});else if(a==='add-page'){const p=page('Untitled page',currentPage().template);currentBook().pages.push(p);pageId=p.id;currentBook().lastPageId=pageId;touchPage();render();setTimeout(()=>{$('#page-title').focus();$('#page-title').select();},30);}else if(a==='select-page'){pageId=b.dataset.id;currentBook().lastPageId=pageId;changed();render();}else if(a==='page-menu')pageMenu();else if(a==='duplicate-page'){$('#dialog').close();const p={...structuredClone(currentPage()),id:id(),title:(currentPage().title+' — copy').slice(0,160)};currentBook().pages.splice(currentBook().pages.indexOf(currentPage())+1,0,p);pageId=p.id;currentBook().lastPageId=pageId;touchPage();render();}else if(a==='delete-page')confirmDelete('Move page to Recently deleted?','Your writing and ink will be kept so you can restore this page.',()=>{pageId=trashPage(state,selected,pageId);currentBook().lastPageId=pageId;});else if(a==='move-page-up'||a==='move-page-down'){const ps=currentBook().pages,i=ps.indexOf(currentPage()),j=i+(a==='move-page-up'?-1:1);if(j<0||j>=ps.length)return;[ps[i],ps[j]]=[ps[j],ps[i]];$('#dialog').close();touchPage();render();}else if(a==='tool')setTool(b.dataset.value);else if(a==='color'){inkColor=b.dataset.value;state.settings.penColor=inkColor;changed();syncEngine();document.querySelectorAll('.swatch').forEach(x=>{x.classList.toggle('selected',x.dataset.value===inkColor);x.setAttribute('aria-pressed',x.dataset.value===inkColor);});}else if(a==='undo')undoInk();else if(a==='redo')undoInk(true);else if(a==='focus'){focus=!focus;$('.editor').classList.toggle('focus-mode',focus);b.setAttribute('aria-pressed',focus);}else if(a==='page-panel'){if(innerWidth>760){focus=false;$('.editor').classList.remove('focus-mode');$('.editor').classList.toggle('pages-collapsed');}else $('.editor').classList.toggle('pages-visible');}else if(a==='zoom-in')applyZoom(zoom+.1);else if(a==='zoom-out')applyZoom(zoom-.1);else if(a==='zoom-fit')applyZoom(($('.paper-scroll').clientWidth-48)/900);else if(a==='export-page')exportPage();else if(a==='collection-menu'){const c=state.collections.find(c=>c.id===filter);modal('Edit collection.',`<label>Name<input name="title" value="${esc(c.title)}" maxlength="120" required></label><div class="detail-actions">${button('delete-collection','Remove collection','trash','danger')}</div>`,'Save',f=>{c.title=f.get('title').trim()||'Collection';changed();render();});$('#dialog [data-action="delete-collection"]').type='button';}else if(a==='delete-collection')confirmDelete('Remove this collection?','Your notebooks will be kept under All notebooks.',()=>{for(const n of state.notebooks)if(n.collection===filter)n.collection=null;state.collections=state.collections.filter(c=>c.id!==filter);filter='all';});});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;renderBooks();}else if(e.target.id==='width'){width=Number(e.target.value);state.settings.penWidth=width;changed();syncEngine();}else if(e.target.id==='page-search'){pageQuery=e.target.value;const ids=new Set(matchingPages(currentBook(),pageQuery).map(p=>p.id));document.querySelectorAll('.page-item').forEach(b=>b.hidden=!ids.has(b.dataset.id));$('.page-panel-footer').textContent=ids.size?`${ids.size} ${ids.size===1?'page':'pages'} in view`:'No matching pages';}else if(e.target.id==='page-title'){currentPage().title=e.target.value;touchPage();const item=document.querySelector(`[data-action="select-page"][data-id="${pageId}"] strong`);if(item)item.textContent=e.target.value;}else if(e.target.id==='page-text'){if(e.target.scrollHeight>e.target.clientHeight+2){e.target.value=currentPage().text;toast('This page is full. Add another page to keep writing.');return;}currentPage().text=e.target.value;touchPage();scheduleThumb();}});
document.addEventListener('change',e=>{if(e.target.id==='sort'){sort=e.target.value;renderBooks();}else if(e.target.id==='template'){currentPage().template=e.target.value;touchPage();$('.paper').className=`paper template-${e.target.value}${tool!=='text'?' ink-mode':''}`;scheduleThumb();}else if(e.target.id==='pencil-only'){state.settings.pencilOnly=e.target.checked;if(engine)engine.allowTouchDraw=!e.target.checked;changed();}});$('#import-file').onchange=async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;try{if(f.size>40*1024*1024)throw Error('Please choose a backup smaller than 40 MB.');const incoming=validateState(JSON.parse(await f.text()));modal('Bring your thoughts home.',`<p class="modal-description">Import ${incoming.notebooks.length} notebooks? They will be added alongside your existing notes.</p>`,'Import notebooks',()=>{try{state=mergedState(state,incoming);view='library';filter='all';changed();render();toast('Your notebooks are here.');}catch(err){toast(err.message);}});}catch(err){toast(err.message||'This backup could not be read.');}};
document.addEventListener('keydown',e=>{if($('#dialog').open)return;const typing=['INPUT','TEXTAREA'].includes(document.activeElement?.tagName);if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();view='library';render();$('#search').focus();}if(!typing&&!e.metaKey&&!e.ctrlKey&&!e.altKey&&view==='editor'&&({p:'pen',h:'highlighter',e:'eraser',t:'text'})[e.key.toLowerCase()]){e.preventDefault();setTool(({p:'pen',h:'highlighter',e:'eraser',t:'text'})[e.key.toLowerCase()]);}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='z'&&view==='editor'&&!typing&&!$('#dialog').open){e.preventDefault();undoInk(e.shiftKey);}});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&revision!==savedRevision)saveNow();});window.addEventListener('beforeunload',e=>{if(revision!==savedRevision){saveNow();e.preventDefault();e.returnValue='';}});
try{db=await openStore();const saved=await readState(db);state=saved?validateState(saved):initialState();inkColor=state.settings.penColor||inkColor;width=state.settings.penWidth||width;storageVersion=state.storageRevision||0;if(!saved)await writeState(db,state);render();}catch(err){app.innerHTML='<div class="boot"><span class="wordmark">zero ·</span><h2>Your workspace could not be opened.</h2><p>Storage may be unavailable, or saved data needs recovery.<br>Try reopening this page in a regular Safari window. Existing data has not been replaced.</p><button class="secondary" id="recover">Download stored data for recovery</button></div>';$('#recover').onclick=async()=>{try{if(!db)throw Error();const raw=await readState(db);download(new Blob([JSON.stringify(raw)],{type:'application/json'}),'zero-recovery.json');}catch{toast('Storage is unavailable in this browser session.');}};}
let updateBusy=false;
// No banner: when a new shell is waiting, the Update buttons light up
// instead (bottom left in the sidebar, and at the top of a notebook).
// Tapping one checks, saves notes, and applies the update.
function markUpdateAvailable(){updateAvailable=true;document.querySelectorAll('[data-action="update-app"]').forEach(b=>{b.classList.add('has-update');});}
function clearUpdateAvailable(){updateAvailable=false;document.querySelectorAll('[data-action="update-app"]').forEach(b=>{b.classList.remove('has-update');});}
async function runUpdate(){if(updateBusy)return;updateBusy=true;document.querySelectorAll('[data-action="update-app"]').forEach(b=>{b.disabled=true;});toast('Saving your notes…');try{if(engine?.activePenId!==null)engine.commitPenStroke();await saveNow();}catch{updateBusy=false;document.querySelectorAll('[data-action="update-app"]').forEach(b=>{b.disabled=false;});toast('Could not save, so Zero was not reloaded.');return;}if(!('serviceWorker'in navigator)){updateBusy=false;document.querySelectorAll('[data-action="update-app"]').forEach(b=>{b.disabled=false;});toast('Open Zero from its installed page to update.');return;}const found=await checkForUpdate();if(found.status==='apply'){const worker=found.registration.waiting||found.registration.installing;await whenInstalled(worker);const waiting=found.registration.waiting||worker;if(waiting&&waiting.state!=='redundant'){waiting.postMessage({type:'SKIP_WAITING'});toast('Updating…');setTimeout(()=>location.reload(),2500);return;}updateBusy=false;document.querySelectorAll('[data-action="update-app"]').forEach(b=>{b.disabled=false;});toast('Could not install the update. Try again.');return;}updateBusy=false;document.querySelectorAll('[data-action="update-app"]').forEach(b=>{b.disabled=false;});clearUpdateAvailable();toast(found.status==='offline'?'You appear to be offline. Try Update again when you are back online.':found.status==='unavailable'?'Open Zero from its installed page to update.':'You are up to date.');}
const updateSecure=location.protocol==='https:'||location.hostname==='localhost'||location.hostname==='127.0.0.1';
if('serviceWorker'in navigator)bindUpdate(navigator.serviceWorker,{secure:updateSecure,onWaiting:markUpdateAvailable});
